-- =====================================================================
-- 0025 — Perfis comportamentais (DISC) da equipe — aba em Gestão
-- Visibilidade: gerente vê todos; líder vê colaboradores (não vê gerente);
-- colaborador não tem acesso. Rode DEPOIS das anteriores.
-- =====================================================================

create table if not exists perfis_comportamentais (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid references profiles(id) on delete set null,
  nome text not null,
  email text not null unique,
  papel text not null default 'colaborador'
    check (papel in ('gerente', 'lider', 'colaborador')),
  pesquisa text,
  concluido_em date,
  perfil_primario text not null check (perfil_primario in ('D', 'I', 'S', 'C')),
  perfil_secundario text check (perfil_secundario in ('D', 'I', 'S', 'C')),
  dados jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table perfis_comportamentais enable row level security;

-- Papel efetivo da pessoa do perfil: o do usuário vinculado (se existir)
-- ou o papel informado no cadastro do perfil.
create or replace function public.perfil_papel_efetivo(p_profile uuid, p_papel text)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select p.role::text from profiles p where p.id = p_profile), p_papel);
$$;

drop policy if exists "perfis_comp_select" on perfis_comportamentais;
create policy "perfis_comp_select" on perfis_comportamentais
  for select using (
    public.eh_gerente()
    or (
      public.eh_lideranca()
      and public.perfil_papel_efetivo(profile_id, papel) <> 'gerente'
    )
  );

drop policy if exists "perfis_comp_write" on perfis_comportamentais;
create policy "perfis_comp_write" on perfis_comportamentais for all
  using (public.eh_gerente()) with check (public.eh_gerente());

